export function AuthorByline({
  authorName = "{{authorName}}",
  role = "{{role}}",
  date = "{{date}}",
  showAvatar = {{showAvatar}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, font: "14px system-ui, sans-serif", color: "#241430" }}>
      {showAvatar && (
        <span aria-hidden="true" style={{ width: 36, height: 36, borderRadius: "50%", display: "flex",
          alignItems: "center", justifyContent: "center", fontSize: 16, flexShrink: 0, background: accent }}>
          &#128100;
        </span>
      )}
      <p style={{ margin: 0, display: "flex", alignItems: "center", gap: 6 }}>
        <span style={{ fontWeight: 600 }}>{authorName}</span>
        <span style={{ color: "#241430aa" }}>{role}</span>
        <span aria-hidden="true">&middot;</span>
        <time style={{ color: "#241430aa" }}>{date}</time>
      </p>
    </div>
  );
}
